  for (let p = Object.getPrototypeOf(el); p && p !== Object.prototype; p = Object.getPrototypeOf(p)) {
    const d = Object.getOwnPropertyDescriptor(p, 'value');
    if (d?.set) { setter = d.set; break; }
  }
  if (setter) setter.call(el, v); else el.value = v;
  el.dispatchEvent(new Event('input', { bubbles: true }));
  el.dispatchEvent(new Event('change', { bubbles: true }));
  el.dispatchEvent(new Event('blur', { bubbles: true }));
}).apply(null, arguments)"""


# Same reader as the extension (content.js readElementValue), run in the page.
_READ_VAL_JS = r"""return ((el, from, attr) => {
  const tag = String(el.tagName || '').toUpperCase(), fld = tag === 'INPUT' || tag === 'TEXTAREA';
  const txt = () => (typeof el.innerText === 'string' ? el.innerText : (el.textContent || ''));
  const ws = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
  if (from === 'attr') return el.getAttribute(attr) ?? '';
  if (from === 'value') {
    if (tag === 'SELECT' && el.multiple) return Array.from(el.selectedOptions).map(o => o.value).join(', ');
    if (fld || tag === 'SELECT') return el.value ?? '';
    if (el.isContentEditable) return txt().trim();
    if (typeof el.value === 'string' && el.value !== '') return el.value;
    if (typeof el.value === 'number' && tag !== 'LI') return String(el.value);
    return txt().trim();
  }
  if (from === 'visible') {
    if (tag === 'SELECT') return Array.from(el.selectedOptions).map(o => ws(o.text)).join(', ');
    if (fld) return el.value ?? '';
    return ws(txt());
  }
  return (el.textContent || '').trim();
}).apply(null, arguments)"""


def _read_val(el, read_from, attr=""):
    return driver.execute_script(_READ_VAL_JS, el, read_from, attr) or ""


def _rows(name):
    """The rows of the CSV file of that name beside this file, each {column: value}."""
    with open(os.path.join(os.path.dirname(os.path.abspath(__file__)), name), encoding="utf-8-sig", newline="") as f:
        text = f.read()
    counts = {",": 0, ";": 0, "\t": 0}
    quote = False
    for ch in text:
        if ch == '"':
            quote = not quote
        elif not quote and ch in "\r\n":
            break
        elif not quote and ch in counts:
            counts[ch] += 1
    delimiter = max(counts, key=counts.get)
    records, record, field, quoted, in_quote, dirty, i = [], [], "", False, False, False, 0

    def end_field():
        nonlocal field, quoted
        record.append(field if quoted else field.strip())
        field, quoted = "", False

    def end_record():
        nonlocal record, dirty
        end_field()
        if dirty:
            records.append(record)
        record, dirty = [], False

    while i < len(text):
        ch = text[i]
        if in_quote:
            if ch == '"' and text[i + 1:i + 2] == '"':
                field += '"'
                i += 1
            elif ch == '"':
                in_quote = False
            else:
                field += ch
        elif ch == '"':
            in_quote = quoted = dirty = True
        elif ch == delimiter:
            end_field()
            dirty = True
        elif ch == "\r":
            if text[i + 1:i + 2] == "\n":
                i += 1
            end_record()
        elif ch == "\n":
            end_record()
        else:
            field += ch
            dirty = True
        i += 1
    if dirty:
        end_record()
    if len(records) < 2:
        raise Exception(f"{name}: a header row and at least one row of data are needed")
    return [{h: (r[k] if k < len(r) else "") for k, h in enumerate(records[0])} for r in records[1:]]


def _column(row, name):
    """The row's value of a column a step needs."""
    if name not in row:
        raise Exception(f'the data file has no column "{name}"')
    return row[name]


